/**
 * Circular delay line per channel. All storage allocated in prepare().
 * RT-safe after prepare: setDelaySamples and pushPop only touch indices and samples.
 */
template <typename FloatType>
class LookaheadDelay
{
public:
    LookaheadDelay() = default;

    void prepare (int numChannels, int maxDelaySamples)
    {
        numChannels = std::max (1, numChannels);
        maxDelaySamples = std::max (0, maxDelaySamples);

        channels_.assign ((size_t) numChannels, {});
        for (auto& ch : channels_)
            ch.assign ((size_t) maxDelaySamples + 1u, FloatType {});

        write_.assign ((size_t) numChannels, 0);
        maxDelaySamples_ = maxDelaySamples;
        delaySamples_ = std::min (delaySamples_, maxDelaySamples_);
    }

    void setDelaySamples (int delaySamples) noexcept
    {
        delaySamples_ = std::clamp (delaySamples, 0, maxDelaySamples_);
    }

    int getDelaySamples() const noexcept { return delaySamples_; }
    int getMaxDelaySamples() const noexcept { return maxDelaySamples_; }

    void reset() noexcept
    {
        for (auto& ch : channels_)
            std::fill (ch.begin(), ch.end(), FloatType {});

        std::fill (write_.begin(), write_.end(), 0);
    }

    FloatType pushPop (int channel, FloatType in) noexcept
    {
        if (channels_.empty())
            return in;

        const int nch = (int) channels_.size();
        const int ch = std::clamp (channel, 0, nch - 1);
        auto& buf = channels_[(size_t) ch];
        if (buf.empty())
            return in;

        const int cap = (int) buf.size();
        const int w = write_[(size_t) ch];
        const int readIndex = (w - delaySamples_ + cap) % cap;
        const FloatType out = buf[(size_t) readIndex];
        buf[(size_t) w] = in;
        write_[(size_t) ch] = (w + 1) % cap;
        return out;
    }

private:
    std::vector<std::vector<FloatType>> channels_;
