/** Sample-peak detector (stereo or mono). Stateless; prepare/reset are no-ops. */
class PeakDetector
{
public:
    PeakDetector() = default;

    void prepare (int /*numChannels*/) noexcept {}
    void reset() noexcept {}

    float process (const float* const* channelPtrs, int numChannels, int sampleIndex) const noexcept
    {
        if (channelPtrs == nullptr || numChannels <= 0)
            return 0.0f;

        float m = 0.0f;
        for (int ch = 0; ch < numChannels; ++ch)
        {
            const float* p = channelPtrs[ch];
            if (p == nullptr)
                continue;

            const float v = std::abs (p[sampleIndex]);
            m = std::max (m, v);
        }

        return m;
    }
};

