LimiterEnvelope::LimiterEnvelope() = default;

void LimiterEnvelope::prepare (const Spec& spec)
{
    sampleRate_ = (spec.sampleRate > 0.0 ? spec.sampleRate : 48000.0);
    lookaheadSamples_ = std::max (1, spec.lookaheadSamples);
    maxBlockSize_ = std::max (1, spec.maxBlockSize);

    attackTable_.assign ((size_t) lookaheadSamples_, 0.0f);
    recomputeAttackSamples();

    ext_.assign ((size_t) lookaheadSamples_ + (size_t) maxBlockSize_, 1.0f);
    historyPost_.assign ((size_t) lookaheadSamples_, 1.0f);

    stage1_ = 1.0f;
    stage2_ = 1.0f;
    stage1Slow_ = 1.0f;
    stage2Slow_ = 1.0f;
    lastBlockMaxGrDb_ = 0.0f;

    recomputeAlpha();
}

void LimiterEnvelope::reset() noexcept
{
    std::fill (ext_.begin(), ext_.end(), 1.0f);
    std::fill (historyPost_.begin(), historyPost_.end(), 1.0f);
    stage1_ = 1.0f;
    stage2_ = 1.0f;
    stage1Slow_ = 1.0f;
    stage2Slow_ = 1.0f;
    lastBlockMaxGrDb_ = 0.0f;
}

