TruePeakDetector::TruePeakDetector() = default;

void TruePeakDetector::prepare (const Spec& spec)
{
    spec_ = spec;
    const int nch = juce::jlimit (1, 2, spec.numChannels);
    const int nbs = juce::jmax (1, spec.maxBlockSize);
    downScratch_.setSize (nch, nbs, false, false, true);
    oversampler_.initProcessing ((size_t) nbs);
    oversampler_.reset();
}

void TruePeakDetector::reset() noexcept
{
    oversampler_.reset();
}

float TruePeakDetector::measure (const juce::AudioBuffer<float>& buffer) noexcept
{
    const int n = buffer.getNumSamples();
    const int nch = juce::jmin (juce::jmin (2, spec_.numChannels), buffer.getNumChannels());
    if (n <= 0 || nch <= 0)
        return 0.0f;

    const int nSafe = juce::jmin (n, downScratch_.getNumSamples());
    auto inBlock = juce::dsp::AudioBlock<const float> (buffer)
                       .getSubsetChannelBlock (0, (size_t) nch)
                       .getSubBlock (0, (size_t) nSafe);

    auto osBlock = oversampler_.processSamplesUp (inBlock);

    float peak = 0.0f;
    for (size_t c = 0; c < osBlock.getNumChannels(); ++c)
    {
        const float* d = osBlock.getChannelPointer (c);
        for (size_t i = 0; i < osBlock.getNumSamples(); ++i)
            peak = juce::jmax (peak, std::abs (d[i]));
    }

    auto downBlock = juce::dsp::AudioBlock<float> (downScratch_)
                         .getSubsetChannelBlock (0, (size_t) nch)
                         .getSubBlock (0, (size_t) nSafe);
    oversampler_.processSamplesDown (downBlock);

    return peak;
}

int TruePeakDetector::getLatencyInSamples() const noexcept
{
    return (int) std::llround ((double) oversampler_.getLatencyInSamples());
}

