    void setValidator (Validator validator) { validator_ = std::move (validator); }
    void setOnSnapshot (OnSnapshot onSnapshot) { onSnapshot_ = std::move (onSnapshot); }

    void setMinCallbackIntervalMs (double ms) noexcept
    {
        minCallbackIntervalMs_ = juce::jmax (0.0, ms);
    }

    void start (int hz)
    {
        active_ = true;
        startTimerHz (juce::jmax (1, hz));
    }

    void stop()
    {
        if (! active_ && supplier_ == nullptr && validator_ == nullptr && onSnapshot_ == nullptr)
            return;

        active_ = false;
        stopTimer();
        pendingDirty_ = false;
        supplier_ = nullptr;
        validator_ = nullptr;
        onSnapshot_ = nullptr;
    }

