LogFrequencyMapper::LogFrequencyMapper()
{
    logFreqMin_  = std::log10 (kDefaultFreqMinHz);
    logFreqMax_  = std::log10 (kDefaultFreqMaxHz);
    logFreqSpan_ = logFreqMax_ - logFreqMin_;
}

LogFrequencyMapper::LogFrequencyMapper (float freqMinHz, float freqMaxHz)
{
    setFrequencyRange (freqMinHz, freqMaxHz);
}

void LogFrequencyMapper::setFrequencyRange (float freqMinHz, float freqMaxHz)
{
    freqMinHz_ = juce::jmax (1.0f, freqMinHz);
    freqMaxHz_ = juce::jmax (freqMinHz_, freqMaxHz);
    logFreqMin_  = std::log10 (freqMinHz_);
    logFreqMax_  = std::log10 (freqMaxHz_);
    logFreqSpan_ = logFreqMax_ - logFreqMin_;
}

float LogFrequencyMapper::freqToProportion (float freqHz) const noexcept
{
    if (freqHz <= 0.0f || logFreqSpan_ <= 0.0f)
        return 0.0f;
    const float logF = std::log10 (juce::jmax (1.0f, freqHz));
    return juce::jlimit (0.0f, 1.0f, (logF - logFreqMin_) / logFreqSpan_);
}

float LogFrequencyMapper::proportionToFreq (float proportion) const noexcept
{
    if (proportion <= 0.0f)
        return freqMinHz_;
    if (proportion >= 1.0f)
        return freqMaxHz_;
    const float logF = logFreqMin_ + proportion * logFreqSpan_;
    return std::pow (10.0f, logF);
}

float LogFrequencyMapper::linearBinProportionToLogProportion (float linearProportion) const noexcept
{
    if (linearProportion <= 0.0f)
        return 0.0f;
    if (linearProportion >= 1.0f)
        return 1.0f;
    // Map linear (0..1 over bins, DC to Nyquist) to log freq proportion.
    const float nyquist = freqMaxHz_;  // Assume display covers up to Nyquist
    const float freq = freqMinHz_ + linearProportion * (freqMaxHz_ - freqMinHz_);
    return freqToProportion (freq);
}

