AnalyzerRenderStateBuilder::PrepareResult AnalyzerRenderStateBuilder::prepareFftTraces (
    const mdsp_dsp::AnalyzerSnapshot& snapshot,
    const PrepareConfig& config,
    std::vector<float>& uiHeldPeak)
{
    PrepareResult out;

    const int fftBinCount = (snapshot.fftBinCount > 0) ? snapshot.fftBinCount : snapshot.numBins;
    if (! snapshot.isValid || fftBinCount <= 0)
    {
        out.noDataReason = "No Data";
        return out;
    }

    out.validBins = fftBinCount;
    out.expectedBins = snapshot.fftSize / 2 + 1;

    if (out.validBins != out.expectedBins || (config.expectedBinsFromMeta > 0 && out.validBins != config.expectedBinsFromMeta))
    {
        out.binMismatch = true;
        out.noDataReason = "Bin Mismatch";
        return out;
    }

    const size_t validBinsSize = static_cast<size_t> (out.validBins);
    out.validBinsSize = validBinsSize;
    const size_t safeCopyBins = std::min (validBinsSize, static_cast<size_t> (mdsp_dsp::AnalyzerSnapshot::kMaxFFTBins));

    out.fftDb.resize (validBinsSize);
    out.fftPeakDb.resize (validBinsSize);

    std::copy (snapshot.fftDb.begin(),
               snapshot.fftDb.begin() + static_cast<std::ptrdiff_t> (safeCopyBins),
               out.fftDb.begin());

    if (snapshot.fftPeakDb.size() >= safeCopyBins)
    {
        std::copy (snapshot.fftPeakDb.begin(),
                   snapshot.fftPeakDb.begin() + static_cast<std::ptrdiff_t> (safeCopyBins),
                   out.fftPeakDb.begin());
