/*
  ==============================================================================

    Melech_SpectralComparator.h
    Part of the MelechDSP HQ Shared Modules.

    PURPOSE:
    Compares two spectral fingerprints and returns a similarity score (0.0 to 1.0).
    It uses Cosine Similarity, which measures the "angle" between two vectors.

    USAGE:
    float score = Melech_SpectralComparator::getSimilarity(targetProfile, inputProfile);

  ==============================================================================
*/

#pragma once
#include <vector>
#include <cmath>

namespace melechdsp
{

    class SpectralComparator
    {
    public:
        /** Compares two spectral vectors.
            Returns 1.0 if they are identical shapes.
            Returns 0.0 if they are completely different (orthogonal).
        */
        static float getSimilarity(const std::vector<float>& profileA, const std::vector<float>& profileB)
        {
            // Safety Check: Vectors must be the same size (same FFT order)
            if (profileA.size() != profileB.size() || profileA.empty())
                return 0.0f;

            float dotProduct = 0.0f;
            float magnitudeA = 0.0f;
            float magnitudeB = 0.0f;

            // Loop through every frequency bin
            for (size_t i = 0; i < profileA.size(); ++i)
            {
                float valA = profileA[i];
                float valB = profileB[i];

                dotProduct += valA * valB;
                magnitudeA += valA * valA;
                magnitudeB += valB * valB;
            }

            // Prevent division by zero if one signal is silence
            if (magnitudeA < 0.00001f || magnitudeB < 0.00001f)
                return 0.0f;

            // Cosine Similarity Formula: (A . B) / (||A|| * ||B||)
            return dotProduct / (std::sqrt(magnitudeA) * std::sqrt(magnitudeB));
        }
    };

} // namespace melechdsp

