class MultiTraceSpec
{
public:
    explicit MultiTraceSpec (size_t expectedBins = 0, size_t maxTraces = 0) noexcept
        : expectedBins_ (expectedBins), maxTraces_ (maxTraces)
    {
    }

    size_t getExpectedBins() const noexcept { return expectedBins_; }
    size_t getMaxTraces() const noexcept { return maxTraces_; }

    bool validateBins (size_t bins) const noexcept
    {
        return expectedBins_ == 0 || bins == expectedBins_;
    }

    void sanitizeBuffer (std::span<const float> in, std::vector<float>& out) const
    {
        out.clear();
        if (!validateBins (in.size()))
            return;

        out.resize (in.size(), -200.0f);
        for (size_t i = 0; i < in.size(); ++i)
            out[i] = std::isfinite (in[i]) ? in[i] : -200.0f;
    }

private:
    size_t expectedBins_ = 0;
    size_t maxTraces_ = 0;
};

