/**
    Contract:
    - Paths are built during model/controller update, never inside paint.
    - Paint must consume cached paths only.
    - Plot-rect changes must call invalidateForPlotChange() (primary mechanism).
    - Cache-key mismatch is a safety net, not the primary invalidation path.
    - Per-trace data changes should call invalidateForDataChange(id).
    - invalidateAll() is for structural/global resets.
    - Multi-trace signal gating must use MultiTraceState::hasSignalAboveThreshold().
*/
class MultiTracePathCache
{
public:
    struct BuildParams
    {
        const RTAGeometry& geometry;
        float minHz = 20.0f;
        float maxHz = 20000.0f;
        float topDb = 6.0f;
        float bottomDb = -200.0f;
        float displayGainDb = 0.0f;
        double sampleRate = 48000.0;
        int fftSize = 2048;
        ::rta::TiltMode tiltMode = ::rta::TiltMode::Flat;
    };

    void invalidateAll();
    void invalidateForPlotChange();
    void invalidateForDataChange (TraceId id);

    void rebuildPaths (const MultiTraceState& state, const BuildParams& params);

    const juce::Path& getPath (TraceId id) const;
    juce::Path& getPath (TraceId id);
    bool isPathBuilt (TraceId id) const;
#if JUCE_DEBUG
    int getDebugDirtyCount() const;
#endif

private:
    struct CachedPath
    {
        juce::Path path;
        bool dirty = true;
    };

    static constexpr size_t toIndex (TraceId id)
    {
        return static_cast<size_t> (id);
    }

    void buildPathForTrace (TraceId id,
                            const std::vector<float>& data,
                            const BuildParams& params,
                            juce::Path& outPath) const;

    std::array<CachedPath, MultiTraceState::kTraceCount> cache_;
    bool plotDirty_ = true;
};

