static inline bool isValidMapping (const AxisMapping& m, float plotLengthPx) noexcept
{
    if (plotLengthPx <= 0.0f)
        return false;

    if (m.scale == AxisScale::Log10)
    {
        return m.minValue > 0.0f && m.maxValue > m.minValue;
    }
    else // Linear
    {
        return m.maxValue > m.minValue;
    }
}

float AxisInteraction::valueToPosPx (const AxisMapping& m, float value, float plotLengthPx) noexcept
{
    if (! isValidMapping (m, plotLengthPx))
        return 0.0f;

    // Clamp value to valid range
    const float clampedValue = std::clamp (value, m.minValue, m.maxValue);

    if (m.scale == AxisScale::Log10)
    {
        const float logMin = std::log10 (m.minValue);
        const float logMax = std::log10 (m.maxValue);
        const float logValue = std::log10 (clampedValue);
        const float logRange = logMax - logMin;

        if (logRange <= 0.0f)
            return 0.0f;

        const float normalized = (logValue - logMin) / logRange;
        return normalized * plotLengthPx;
    }
    else // Linear
    {
        const float range = m.maxValue - m.minValue;
        if (range <= 0.0f)
            return 0.0f;

        const float normalized = (clampedValue - m.minValue) / range;
        return normalized * plotLengthPx;
    }
}

