void paintIcon (juce::Graphics& g,
                const UiContext& ui,
                IconId id,
                juce::Rectangle<float> bounds,
                juce::Colour tint,
                float alpha)
{
    // Clamp alpha to [0..1]
    alpha = std::clamp(alpha, 0.0f, 1.0f);

    // Early return if bounds empty or alpha <= 0
    if (bounds.isEmpty() || alpha <= 0.0f)
        return;

    // If tint is fully transparent, use base drawable (cached, no allocation)
    if (tint.getAlpha() == 0)
    {
        const juce::Drawable* drawable = ui.icons().get(id);
        if (drawable != nullptr)
        {
            drawable->drawWithin(g, bounds, juce::RectanglePlacement::centred | juce::RectanglePlacement::onlyReduceInSize, 1.0f);
        }
    }
    else
    {
        // Get tinted copy (allocates, but expected for tinted icons)
        auto tintedDrawable = ui.icons().makeTinted(id, tint, alpha);
        if (tintedDrawable != nullptr)
        {
            tintedDrawable->drawWithin(g, bounds, juce::RectanglePlacement::centred | juce::RectanglePlacement::onlyReduceInSize, 1.0f);
        }
    }
}

