std::unique_ptr<juce::Drawable> IconCache::makeTinted(IconId id, juce::Colour c, float alpha) const
{
    const juce::Drawable* base = getOrLoad(id);
    if (base == nullptr)
        return nullptr;

    // Create a deep copy
    std::unique_ptr<juce::Drawable> tinted = base->createCopy();
    if (tinted == nullptr)
        return nullptr;

    // Apply tint
    applyTint(*tinted, c, alpha);

    return tinted;
}

const juce::Drawable* IconCache::getOrLoad(IconId id) const
{
    std::lock_guard<std::mutex> lock(mutex_);

    // Check cache first
    auto it = cache_.find(id);
    if (it != cache_.end())
        return it->second.get();

    // Load and cache
    std::unique_ptr<juce::Drawable> drawable = loadIcon(id);
    if (drawable == nullptr)
        return nullptr;

    const juce::Drawable* result = drawable.get();
    cache_[id] = std::move(drawable);

    return result;
}

