    LegendResult LegendRenderer::draw (
        juce::Graphics& g,
        const juce::Rectangle<float>& plotBounds,
        const Theme& theme,
        const LegendItem* items,
        int numItems,
        LegendEdge edge,
        const LegendStyle& style)
    {
        LegendResult result;

        if (numItems <= 0 || ! items)
            return result;

        // Clamp alphas to [0..1]
        const float textAlphaClamped = juce::jlimit (0.0f, 1.0f, style.textAlpha);
        const float disabledAlphaClamped = juce::jlimit (0.0f, 1.0f, style.disabledAlpha);
        const float frameBorderAlphaClamped = juce::jlimit (0.0f, 1.0f, style.frameBorderAlpha);
        const float frameFillAlphaClamped = juce::jlimit (0.0f, 1.0f, style.frameFillAlpha);

        // Measure text widths to compute total width
        const juce::Font font (juce::FontOptions().withHeight (style.fontHeightPx));
        g.setFont (font);

        float totalWidth = 0.0f;
        int enabledCount = 0;

        for (int i = 0; i < numItems; ++i)
        {
            if (! items[i].enabled)
                continue;

            ++enabledCount;
            // Use GlyphArrangement to measure text width (non-deprecated)
            juce::GlyphArrangement glyphs;
            glyphs.addFittedText (font, items[i].label, 0.0f, 0.0f, 10000.0f, style.fontHeightPx, juce::Justification::left, 1);
            const float textWidth = glyphs.getBoundingBox (0, -1, true).getWidth();
            totalWidth += style.swatchSizePx + style.swatchTextGapPx + textWidth;

            if (i < numItems - 1)
                totalWidth += style.itemGapPx;
        }

        // If no enabled items, return empty result
        if (enabledCount == 0)
            return result;

