    void TextOverlayRenderer::draw (
        juce::Graphics& g,
        juce::Rectangle<float> bounds,
        const Theme& theme,
        const juce::String& text,
        const TextOverlayStyle& style)
    {
        if (text.isEmpty())
            return;

        // Clamp alpha to [0..1]
        const float alphaClamped = juce::jlimit (0.0f, 1.0f, style.alpha);

        // Apply padding by reducing bounds
        if (style.paddingPx > 0.0f)
        {
            bounds = bounds.reduced (style.paddingPx);
        }

        // Set up clipping if requested
        juce::Graphics::ScopedSaveState clipState (g);
        if (style.clipToBounds)
        {
            g.reduceClipRegion (bounds.toNearestInt());
        }

        // Determine colour
        juce::Colour textColour;
        if (style.colourOverride.has_value())
        {
            // Use explicit override (with alpha)
            textColour = style.colourOverride.value().withAlpha (alphaClamped);
        }
        else
        {
            // Use theme colour (text or textMuted)
            const juce::Colour baseColour = style.useMuted ? theme.textMuted : theme.text;
            textColour = baseColour.withAlpha (alphaClamped);
        }

        // Set colour
        g.setColour (textColour);

        // Set font using FontOptions (no deprecated ctor)
        g.setFont (juce::Font (juce::FontOptions().withHeight (style.fontHeightPx)));

        // Draw text
        g.drawText (text, bounds.toNearestInt(), style.justification, true);
    }

