PlotFrameResult PlotFrameRenderer::draw (juce::Graphics& g,
                                         juce::Rectangle<float> bounds,
                                         const Theme& theme,
                                         const PlotFrameStyle& style)
{
    PlotFrameResult result;

    // Apply inset first
    juce::Rectangle<float> frame = bounds.reduced (style.insetPx);
    result.frame = frame;

    // Guard against empty frame
    if (frame.isEmpty() || frame.getWidth() <= 0.0f || frame.getHeight() <= 0.0f)
    {
        result.inner = frame;
        return result;
    }

    // Compute inner rect (after border)
    const float borderThickness = std::max (0.0f, style.borderThicknessPx);
    juce::Rectangle<float> inner = frame.reduced (borderThickness);

    // Guard against negative inner size
    if (inner.getWidth() < 0.0f || inner.getHeight() < 0.0f)
        inner = frame;

    result.inner = inner;

    // Draw fill
    if (style.drawFill)
    {
        const float fillAlphaClamped = clampAlpha (style.fillAlpha);
        g.setColour (theme.panel.withAlpha (fillAlphaClamped));

        if (style.cornerRadiusPx > 0.0f)
        {
            g.fillRoundedRectangle (frame, style.cornerRadiusPx);
        }
        else
        {
            g.fillRect (frame);
        }
    }

    // Draw border
    if (style.drawBorder && borderThickness > 0.0f)
    {
        const float borderAlphaClamped = clampAlpha (style.borderAlpha);
        g.setColour (theme.gridMajor.withAlpha (borderAlphaClamped));

        if (style.cornerRadiusPx > 0.0f)
        {
            g.drawRoundedRectangle (frame, style.cornerRadiusPx, borderThickness);
        }
        else
        {
            g.drawRect (frame, borderThickness);
        }
    }

