static void getTextButtonStateColours (const juce::Button& b, const ButtonStyle& s,
                                       juce::Colour& bgColour, juce::Colour& borderColour)
{
    bgColour = s.bg;
    borderColour = s.border;
    if (! b.isEnabled())
    {
        bgColour = s.bgDisabled;
        borderColour = s.border.withMultipliedAlpha (0.5f);
    }
    else if (b.isDown())
    {
        bgColour = s.bgDown;
        borderColour = s.borderDown;
    }
    else if (b.isOver())
    {
        bgColour = s.bgHover;
        borderColour = s.borderHover;
    }
}

