bool AxisHoverController::updateFromCursorPx (float cursorPosPx,
                                               float axisLengthPx,
                                               const AxisMapping& mapping,
                                               const juce::Array<AxisTick>& ticks)
{
    // Clamp cursorPosPx into [0..axisLengthPx]
    const float clampedPosPx = juce::jlimit (0.0f, axisLengthPx, cursorPosPx);

    // Hit test using AxisInteraction
    const AxisHitTest hit = AxisInteraction::hitTest (clampedPosPx, axisLengthPx, mapping, ticks, style_.snap);

    // Build new state
    AxisHoverState newState;
    newState.active = hit.active;
    newState.cursorPosPx = hit.posPx;  // Use resolved position (snapped if applicable)
    newState.value = hit.snapped ? hit.snappedValue : hit.value;
    newState.snappedTickIndex = hit.tickIndex;

    // Change detection: compare old/new with epsilon
    bool changed = false;

    // Active state: exact bool comparison
    if (newState.active != state_.active)
        changed = true;

    // Position: epsilon comparison
    if (std::abs (newState.cursorPosPx - state_.cursorPosPx) > style_.epsPosPx)
        changed = true;

    // Value: epsilon comparison
    if (std::abs (newState.value - state_.value) > style_.epsValue)
        changed = true;

    // Tick index: exact int comparison
    if (newState.snappedTickIndex != state_.snappedTickIndex)
        changed = true;

    // Update state if changed
    if (changed)
        state_ = newState;

    return changed;
}

