                                                float cursorYpx,
                                                float plotWidthPx,
                                                float plotHeightPx,
                                                const AxisMapping& xMapping,
                                                const juce::Array<AxisTick>& xTicks,
                                                const AxisSnapOptions& xSnap,
                                                const AxisMapping& yMapping,
                                                const juce::Array<AxisTick>& yTicks,
                                                const AxisSnapOptions& ySnap)
{
    // Update X-axis controller
    bool xChanged = x_.updateFromCursorPx (cursorXpx, plotWidthPx, xMapping, xTicks);

    // Update Y-axis controller
    // Note: Y-axis typically increases downward in screen coordinates, but mapping may invert
    // The controller handles clamping and hit testing internally
    bool yChanged = y_.updateFromCursorPx (cursorYpx, plotHeightPx, yMapping, yTicks);

    // Update combined state
    state_.x = x_.state();
    state_.y = y_.state();

    return xChanged || yChanged;
}

