    const float logMin   = std::log10 (input.minHz);
    const float logMax   = std::log10 (input.maxHz);
    const float logRange = logMax - logMin;
    if (logRange <= 0.0f)
        return input.plotLeft;

    const float logFreq = std::log10 (std::clamp (freqHz, input.minHz, input.maxHz));
    const float norm    = std::clamp ((logFreq - logMin) / logRange, 0.0f, 1.0f);
    return input.plotLeft + norm * input.plotWidth;
}

float mapDbToY (float db, const AxisLayoutModel::Input& input)
{
    const float range = input.topDb - input.bottomDb;
    if (range <= 0.0f || input.plotHeight <= 0.0f)
        return input.plotTop;

    const float norm = (input.topDb - std::clamp (db, input.bottomDb, input.topDb)) / range;
    return input.plotTop + norm * input.plotHeight;
}

