bool nearlyEqual (float a, float b, float epsilon)
{
    return std::abs (a - b) <= epsilon;
}

uint64_t fnv1aAppend (uint64_t hash, const uint8_t* bytes, size_t count)
{
    constexpr uint64_t prime = 1099511628211ull;
    for (size_t i = 0; i < count; ++i)
    {
        hash ^= bytes[i];
        hash *= prime;
    }
    return hash;
}

template <typename T>
uint64_t hashValue (uint64_t seed, const T& value)
{
    return fnv1aAppend (seed, reinterpret_cast<const uint8_t*> (&value), sizeof (T));
}
