bool BackgroundGridCache::Key::operator!= (const Key& other) const
{
    return imageWidth != other.imageWidth
        || imageHeight != other.imageHeight
        || !nearlyEqual (plotLeft, other.plotLeft, 0.5f)
        || !nearlyEqual (plotTop, other.plotTop, 0.5f)
        || !nearlyEqual (plotWidth, other.plotWidth, 0.5f)
        || !nearlyEqual (plotHeight, other.plotHeight, 0.5f)
        || !nearlyEqual (minHz, other.minHz, 1.0e-5f)
        || !nearlyEqual (maxHz, other.maxHz, 1.0e-5f)
        || !nearlyEqual (topDb, other.topDb, 1.0e-5f)
        || !nearlyEqual (bottomDb, other.bottomDb, 1.0e-5f)
        || !nearlyEqual (displayGainDb, other.displayGainDb, 1.0e-5f)
        || viewMode != other.viewMode
        || backgroundArgb != other.backgroundArgb
        || gridArgb != other.gridArgb
        || gridMajorArgb != other.gridMajorArgb
        || textArgb != other.textArgb;
}

