void MultiTracePathCache::rebuildPaths (const MultiTraceState& state, const BuildParams& params)
{
    for (const auto id : state.getOrderedTraces())
    {
        auto& cached = cache_[toIndex (id)];
        if (!cached.dirty && !plotDirty_)
            continue;

        if (!state.isEnabled (id))
        {
            cached.path.clear();
            cached.dirty = false;
            continue;
        }

        buildPathForTrace (id, state.getTraceData (id), params, cached.path);
        cached.dirty = false;
    }

    plotDirty_ = false;
}

