#if JUCE_DEBUG
        jassert (cache.isPathBuilt (tv.id)); // draw=true must never use an unbuilt cache entry
        const auto& cachedPath = cache.getPath (tv.id);
        jassert (!cachedPath.isEmpty()); // draw=true implies a drawable cached path
        jassert (cachedPath.getBounds().isFinite());
#endif

        const auto colour = traceColourFor (theme, tv.id).withAlpha (juce::jlimit (0.0f, 1.0f, tv.alpha));
        drawSilkTrace (g, cache.getPath (tv.id), colour, 1.8f, viewWidth, false, 1.0f, false);
    }
}

