void runMultiTraceSmokeHarnessOnce()
{
    using mdsp_ui::rta::MultiTracePathCache;
    using mdsp_ui::rta::MultiTraceSpec;
    using mdsp_ui::rta::MultiTraceState;
    using mdsp_ui::rta::MultiTraceViewModel;
    using mdsp_ui::rta::TraceId;

    constexpr size_t bins = 512;
    MultiTraceSpec spec (bins, 6);
    MultiTraceState state;
    state.setSpec (spec);

    std::vector<float> left (bins, -200.0f);
    std::vector<float> right (bins, -200.0f);
    std::vector<float> mid (bins, -200.0f);
    std::vector<float> side (bins, -200.0f);
    std::vector<float> mono (bins, -200.0f);
    std::vector<float> stereo (bins, -200.0f);

    for (size_t i = 0; i < bins; ++i)
    {
        const float t = static_cast<float> (i) / static_cast<float> (bins - 1);
        const float wave = std::sin (t * 6.283185307f * 4.0f);
        left[i] = -48.0f + wave * 6.0f;
