        return;
    sink.invalidateBackground();
    sink.invalidatePaths();
}

void RTADisplayInvalidationPolicy::onFrequencyRangeChanged (InvalidationSink& sink,
                                                            float oldMinHz, float oldMaxHz,
                                                            float newMinHz, float newMaxHz) const
{
    if (std::abs (oldMinHz - newMinHz) <= kEpsilonF && std::abs (oldMaxHz - newMaxHz) <= kEpsilonF)
        return;
    sink.invalidateBackground();
    sink.invalidateMultiTraceForPlotChange();
    sink.invalidatePaths();
}

void RTADisplayInvalidationPolicy::onDbRangeChanged (InvalidationSink& sink,
                                                     float oldTopDb, float oldBottomDb,
                                                     float newTopDb, float newBottomDb) const
{
    if (std::abs (oldTopDb - newTopDb) <= kEpsilonF && std::abs (oldBottomDb - newBottomDb) <= kEpsilonF)
        return;
    sink.invalidateBackground();
    sink.invalidateMultiTraceForPlotChange();
    sink.invalidatePaths();
}

void RTADisplayInvalidationPolicy::onDisplayGainChanged (InvalidationSink& sink, float oldDisplayGainDb, float newDisplayGainDb) const
{
    if (std::abs (oldDisplayGainDb - newDisplayGainDb) <= kEpsilonF)
        return;
    sink.invalidateBackground();
    sink.invalidatePaths();
}

