float normalisedFromDb (float db, float minDb, float maxDb)
{
    const float span = std::max (0.001f, maxDb - minDb);
    return std::clamp ((db - minDb) / span, 0.0f, 1.0f);
}

float toValueForKind (const MeterConfig& config, const MeterChannelRenderState& channel)
{
    if (config.kind == MeterKind::GainReduction)
        return -std::abs (channel.grDb);

    if (config.showPeak)
        return channel.peakDb;

    return channel.rmsDb;
}

void drawVerticalChannel (juce::Graphics& g,
                          juce::Rectangle<float> bounds,
                          const MeterConfig& config,
                          const MeterChannelRenderState& channel,
                          const mdsp_ui::Theme& theme)
{
    g.setColour (theme.grid.withAlpha (0.5f));
    g.fillRect (bounds);

    const float valueDb = toValueForKind (config, channel);
    const float fillNorm = normalisedFromDb (valueDb, config.minDb, config.maxDb);
    const float fillHeight = bounds.getHeight() * fillNorm;
    auto fillRect = juce::Rectangle<float> (bounds.getX(), bounds.getBottom() - fillHeight, bounds.getWidth(), fillHeight);

    g.setColour (config.kind == MeterKind::GainReduction ? theme.warning : theme.accent);
    g.fillRect (fillRect);

    if (config.showHold)
    {
        const float holdNorm = normalisedFromDb (channel.holdDb, config.minDb, config.maxDb);
        const float holdY = bounds.getBottom() - bounds.getHeight() * holdNorm;
        g.setColour (theme.seriesHold);
        g.drawLine (bounds.getX(), holdY, bounds.getRight(), holdY, 1.5f);
    }

    if (config.showClip && channel.clip)
    {
        g.setColour (theme.error);
        g.fillRect (bounds.removeFromTop (3.0f));
    }

    g.setColour (theme.gridMajor.withAlpha (0.7f));
    g.drawRect (bounds, 1.0f);
}

