}

float PeakHoldModel::process (float inputDb, float dtSec, const MeterBallisticsConfig& config) noexcept
{
    if (! initialized_)
        reset (inputDb);

    const float holdSec = std::max (config.holdMs, 0.0f) / 1000.0f;

    if (inputDb >= heldDb_)
    {
        heldDb_ = inputDb;
        holdRemainingSec_ = holdSec;
        return heldDb_;
    }

    if (holdRemainingSec_ > 0.0f)
    {
        holdRemainingSec_ = std::max (0.0f, holdRemainingSec_ - std::max (dtSec, 0.0f));
        return heldDb_;
    }

    const float falloff = std::max (config.holdFalloffDbPerSec, 0.0f) * std::max (dtSec, 0.0f);
