void MeterBallistics::reset (float value) noexcept
{
    current_ = value;
    initialized_ = true;
}

float MeterBallistics::process (float target, float dtSec, const MeterBallisticsConfig& config) noexcept
{
    if (! initialized_)
        reset (target);

    const bool rising = target > current_;
    const float coeff = computeCoeff (rising ? config.attackMs : config.releaseMs, dtSec);
    current_ += (target - current_) * coeff;
    return current_;
}

float MeterBallistics::computeCoeff (float timeMs, float dtSec) noexcept
{
    const float safeMs = std::max (timeMs, 0.001f);
    const float tauSec = safeMs / 1000.0f;
    if (dtSec <= 0.0f)
        return 1.0f;
    return 1.0f - std::exp (-dtSec / tauSec);
}

