    auto meterBounds = getLocalBounds().toFloat().reduced (3.0f);

    g.setColour (theme.background.withAlpha (0.75f));
    g.fillRect (meterBounds);
    g.setColour (theme.grid.withAlpha (0.6f));
    g.drawRect (meterBounds, 1.0f);

    if (meterBounds.getHeight() <= 0.0f || meterBounds.getWidth() <= 0.0f)
        return;

