    g.fillRect (liveRect);

    if (state_.holdEnabled)
    {
        const float holdNorm = juce::jlimit (0.0f, 1.0f, state_.holdGrNorm);
        const float y = meterBounds.getBottom() - holdNorm * meterBounds.getHeight();

        g.setColour (theme.text.withAlpha (0.9f));
        g.drawLine (meterBounds.getX(), y, meterBounds.getRight(), y, 1.3f);
    }
