void AnalyzerSessionPolicy::updateSessionMarker (bool holdOn,
                                                 bool usePeaks,
                                                 std::span<const float> fftPeakDb,
                                                 int fftSize,
                                                 double sampleRate,
                                                 float epsilonDb)
{
    if (holdOn && !lastHoldState_)
    {
        sessionMarkerValid_ = false;
        sessionMarkerDb_ = -1000.0f;
    }
    else if (!holdOn && lastHoldState_)
    {
        sessionMarkerValid_ = false;
    }

    if (fftSize != lastFftSize_ || std::abs (sampleRate - lastSampleRate_) > 1.0)
    {
        sessionMarkerValid_ = false;
        sessionMarkerDb_ = -1000.0f;
    }

    lastHoldState_ = holdOn;
    lastFftSize_ = fftSize;
    lastSampleRate_ = sampleRate;

    if (holdOn && usePeaks && !fftPeakDb.empty())
    {
        float currentMax = -1000.0f;
        int maxBin = -1;
        for (size_t i = 0; i < fftPeakDb.size(); ++i)
        {
            if (fftPeakDb[i] > currentMax)
            {
                currentMax = fftPeakDb[i];
                maxBin = static_cast<int> (i);
            }
        }

        if (currentMax > (sessionMarkerDb_ + epsilonDb))
        {
            sessionMarkerDb_ = currentMax;
            sessionMarkerBin_ = maxBin;
            sessionMarkerValid_ = true;
        }
    }
}

