InteractionUpdate AnalyzerController::onMouseMove(juce::Rectangle<int> bounds,
                                                  juce::Point<float> position,
                                                  juce::ModifierKeys)
{
    InteractionUpdate upd;
    const float plotLeft = 50.0f;
    const float plotTop = 10.0f;
    const float plotWidth = static_cast<float>(bounds.getWidth()) - 60.0f;
    const float plotHeight = static_cast<float>(bounds.getHeight()) - 40.0f;
    if (position.x >= plotLeft && position.x <= plotLeft + plotWidth &&
        position.y >= plotTop && position.y <= plotTop + plotHeight)
    {
        upd.hoverActive = true;
        upd.hoverXpx = position.x;
        upd.hoverYpx = position.y;
        const float norm = (position.x - plotLeft) / plotWidth;
        const float minHz = 20.0f;
        const float maxHz = 20000.0f;
        upd.hoverFreqHz = std::pow(10.0f, std::log10(minHz) + norm * (std::log10(maxHz) - std::log10(minHz)));
    }
    return upd;
}

