/**
 * @brief Wrapper around juce::SmoothedValue with consistent setup
 * 
 * Provides a stable API for parameter smoothing with time-based initialization.
 */
template <typename FloatType>
class Smoother
{
public:
    /**
     * @brief Default constructor
     */
    Smoother() = default;

    /**
     * @brief Constructor with sample rate and smoothing time
     * @param sampleRate Sample rate in Hz
     * @param timeMs Smoothing time in milliseconds
     */
    Smoother(double sampleRate, double timeMs)
    {
        reset(sampleRate, timeMs);
    }

    /**
     * @brief Reset with new sample rate and smoothing time
     * @param sampleRate Sample rate in Hz
     * @param timeMs Smoothing time in milliseconds
     */
    void reset(double sampleRate, double timeMs)
    {
        const double timeSeconds = timeMs / 1000.0;
        smoothedValue.reset(sampleRate, timeSeconds);
    }

    /**
     * @brief Set current and target value (no smoothing)
     */
    void setCurrentAndTargetValue(FloatType value)
    {
        smoothedValue.setCurrentAndTargetValue(value);
    }

    /**
     * @brief Set target value (will smooth to this)
     */
    void setTargetValue(FloatType value)
    {
        smoothedValue.setTargetValue(value);
    }

    /**
     * @brief Get next smoothed value (advances internal state)
     */
    FloatType getNextValue()
    {
        return smoothedValue.getNextValue();
    }

    /**
     * @brief Get current smoothed value (doesn't advance state)
     */
    FloatType getCurrentValue() const
    {
        return smoothedValue.getCurrentValue();
    }

    /**
     * @brief Check if currently smoothing
     */
    bool isSmoothing() const
    {
        return smoothedValue.isSmoothing();
    }

private:
    juce::SmoothedValue<FloatType, juce::ValueSmoothingTypes::Linear> smoothedValue;
};
