/**
    Configuration settings for SpectrogramAccumulator.
    Controls FFT size, overlap, windowing type, and frequency scale.
*/
struct SpectrogramSettings
{
    /** FFT order (size = 2^order). Range typically 8-14 (256-16384 samples). */
    int fftOrder = 11;  // Default: 2048 samples

    /** Overlap factor (1 = no overlap, 4 = 75% overlap / 25% hop). Minimum 1, typically 2-8. */
    int overlap = 4;

    /** Windowing function type. */
    enum WindowType
    {
        hann,
        blackmanHarris,
        flatTop,
        rectangular,
        kaiser,
        cosine3
    };

    WindowType windowType = hann;

    /** Frequency scale for output. */
    enum FrequencyScale
    {
        linear,
        logarithmic,
        mel,
        bark
    };

    FrequencyScale frequencyScale = logarithmic;

    /** APVTS parameter ID constants. */
    static constexpr const char* kParamIdFftOrder = "spectrogram_fftOrder";
    static constexpr const char* kParamIdOverlap = "spectrogram_overlap";
    static constexpr const char* kParamIdWindowType = "spectrogram_windowType";
    static constexpr const char* kParamIdFreqScale = "spectrogram_freqScale";

    /** Returns FFT size (2^fftOrder). */
    int getFftSize() const noexcept { return 1 << fftOrder; }

    /** Returns hop size in samples (fftSize / overlap). */
    int getHopSize() const noexcept { return getFftSize() / overlap; }

    /** Validates settings and clamps to valid ranges. */
    void validate() noexcept
    {
        fftOrder = juce::jlimit (8, 14, fftOrder);
        overlap  = juce::jmax (1, overlap);
    }
};

